package in.lmt.commercial;
import in.lmt.shared.*;
import in.lmt.identity.*;
import in.lmt.workspace.WorkspaceCommands;
import in.lmt.catalog.CatalogService;
import java.util.*;
import java.time.*;
import java.util.function.Supplier;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import tools.jackson.databind.ObjectMapper;
@Service @Transactional
public class SubscriptionDowngrades {
 private final JdbcClient db;private final WorkspaceCommands scope;private final IdentityConfig config;private final Audit audit;private final ObjectMapper json;private final Entitlements entitlements;private final CatalogService catalog;private final SubscriptionNotices notices;
 public SubscriptionDowngrades(JdbcClient db,WorkspaceCommands scope,IdentityConfig config,Audit audit,ObjectMapper json,Entitlements entitlements,CatalogService catalog,SubscriptionNotices notices){this.db=db;this.scope=scope;this.config=config;this.audit=audit;this.json=json;this.entitlements=entitlements;this.catalog=catalog;this.notices=notices;}
 public record Quota(String resource,int currentAllowance,int targetAllowance,int used,int reserved,int excess){}
 public record Target(UUID versionId,String name,Integer rentableLimit,Integer managerLimit,boolean eligible,String reason){}
 public record CancellationTerms(String policyVersion,String refundStatus,String refundAmount,String creditStatus,String creditAmount,String currency,String retentionPolicy,String accessConsequences){}
 public record Review(UUID id,UUID targetVersionId,int subscriptionVersion,String fingerprint,String currentPlan,String targetPlan,Instant effectiveAt,Instant expiresAt,List<Quota> quotas,List<String> lostFeatures,List<String> retainedFeatures,String preservation,String mode,CancellationTerms cancellation){}
 public record Request(UUID id,String status,int version,String etag,Review review,int attempts,String lastCode,Instant appliedAt){}
 public record State(UUID workspaceId,String currentPlan,String etag,Instant periodEnd,List<Target> targets,List<Request> requests,String explanation,Instant asOf){}
 public record Claim(UUID id,UUID workspaceId,UUID actorId,UUID token){}
 private String tag(UUID w,int v){return "\"subscription-"+w+"-v"+v+"\"";}
 private String rtag(UUID id,int v){return "\"downgrade-"+id+"-v"+v+"\"";}
 private Instant now(){return db.sql("SELECT clock_timestamp()").query(OffsetDateTime.class).single().toInstant();}
 private Instant instant(Object v){return v==null?null:((java.sql.Timestamp)v).toInstant();}
 private Map<String,Object> subscription(UUID w){return db.sql("SELECT s.*,p.display_name,w.mode,w.status AS workspace_status FROM workspace_subscription s JOIN plan_version p ON p.version_id=s.plan_version_id JOIN workspace w ON w.id=s.workspace_id WHERE s.workspace_id=:w").param("w",w).query().singleRow();}
 private void match(String expected,String actual){if(expected==null||expected.isBlank())throw new ApiProblem(428,"PRECONDITION_REQUIRED","Refresh and review the current subscription or request version.");if(!expected.equals(actual))throw new ApiProblem(412,"VERSION_STALE","The record changed. Refresh and review again.");}
 private void local(Map<String,Object> s){if(db.sql("SELECT count(*) FROM subscription_settlement WHERE workspace_id=:w AND status='reversal_review'").param("w",s.get("workspace_id")).query(Long.class).single()>0)throw new ApiProblem(409,"PAYMENT_REVERSAL_REVIEW_REQUIRED","Resolve the payment reversal before changing subscription terms.");if(!config.sandbox||!s.get("mode").equals("sandbox"))throw new ApiProblem(409,"DOWNGRADE_POLICY_UNAVAILABLE","Live subscription downgrade policy is not configured.");if(s.get("workspace_status").equals("suspended"))throw new ApiProblem(409,"SECURITY_SUSPENDED","Resolve the security suspension before changing the subscription.");}
 private void lock(UUID actor,UUID w){scope.requireOwner(w,actor);db.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","membership:"+w).query().singleRow();db.sql("SELECT id FROM workspace_subscription WHERE workspace_id=:w FOR UPDATE").param("w",w).query(UUID.class).single();scope.requireOwner(w,actor);}
 private <T>T command(UUID actor,UUID w,String operation,UUID key,Object body,Class<T> type,Supplier<T> work){lock(actor,w);String hash=ChallengeService.hash(json.writeValueAsString(body));var prior=db.sql("SELECT request_hash,result::text FROM subscription_downgrade_command WHERE actor_id=:a AND workspace_id=:w AND operation=:o AND request_key=:k").param("a",actor).param("w",w).param("o",operation).param("k",key).query().listOfRows();if(!prior.isEmpty()){if(!hash.equals(prior.getFirst().get("request_hash")))throw new ApiProblem(409,"IDEMPOTENCY_CONFLICT","This key has different downgrade arguments.");return json.readValue((String)prior.getFirst().get("result"),type);}T result=work.get();db.sql("INSERT INTO subscription_downgrade_command(actor_id,workspace_id,operation,request_key,request_hash,result) VALUES(:a,:w,:o,:k,:h,CAST(:r AS jsonb))").param("a",actor).param("w",w).param("o",operation).param("k",key).param("h",hash).param("r",json.writeValueAsString(result)).update();return result;}
 private List<Quota> quotas(UUID w,int units,int managers){return db.sql("SELECT resource,allowance,used,reserved FROM workspace_grant WHERE workspace_id=:w ORDER BY resource").param("w",w).query((r,n)->{int target=r.getString("resource").equals("managers")?managers:units;return new Quota(r.getString("resource"),r.getInt("allowance"),target,r.getInt("used"),r.getInt("reserved"),Math.max(0,r.getInt("used")+r.getInt("reserved")-target));}).list();}
 private List<Target> targets(UUID w,Map<String,Object>s){return catalog.list("workspace","monthly").items().stream().filter(p->!p.versionId().equals(s.get("plan_version_id"))).filter(p->p.rentableLimit()==null||p.managerLimit()==null||quotas(w,p.rentableLimit(),p.managerLimit()).stream().anyMatch(q->q.targetAllowance()<q.currentAllowance())).map(p->{String reason="Eligible at the recorded billing boundary; existing data will be retained.";boolean eligible=true;if(!config.sandbox||!s.get("mode").equals("sandbox")){eligible=false;reason="Live downgrade policy is unavailable.";}else if(!s.get("status").equals("active_paid")||s.get("period_end")==null){eligible=false;reason="No paid billing boundary is recorded for the current subscription.";}else if(!p.code().equals("FREE")||!"0.00".equals(p.amount())){eligible=false;reason="Paid-to-paid renewal pricing and verified settlement are not implemented. No automatic charge or unfunded paid period will be created.";}else if(p.rentableLimit()==null||p.managerLimit()==null||quotas(w,p.rentableLimit(),p.managerLimit()).stream().anyMatch(q->q.targetAllowance()>q.currentAllowance())){eligible=false;reason="The target is not a configured lower-capacity plan.";}return new Target(p.versionId(),p.name(),p.rentableLimit(),p.managerLimit(),eligible,reason);}).toList();}
 private Target target(UUID w,Map<String,Object>s,UUID id){return targets(w,s).stream().filter(t->t.versionId().equals(id)&&t.eligible()).findFirst().orElseThrow(()->new ApiProblem(409,"TARGET_UNAVAILABLE","Select an eligible lower plan with configured billing policy."));}
 private Instant evaluationAt(Instant boundary){Instant current=now();return boundary.isAfter(current)?boundary:current;}
 private String fingerprint(UUID w,UUID p,Instant at){return ChallengeService.hash(json.writeValueAsString(entitlements.previewAt(w,p,evaluationAt(at))));}
 private Review review(UUID w,UUID id){return db.sql("SELECT snapshot::text FROM subscription_downgrade_review WHERE workspace_id=:w AND id=:id").param("w",w).param("id",id).query(String.class).optional().map(s->json.readValue(s,Review.class)).orElseThrow(()->new ApiProblem(404,"REVIEW_NOT_FOUND","Downgrade review is unavailable."));}
 private Request request(UUID w,UUID id){var r=db.sql("SELECT * FROM subscription_downgrade_request WHERE workspace_id=:w AND id=:id").param("w",w).param("id",id).query().listOfRows().stream().findFirst().orElseThrow(()->new ApiProblem(404,"DOWNGRADE_NOT_FOUND","Downgrade is unavailable."));int version=(Integer)r.get("version");return new Request(id,(String)r.get("status"),version,rtag(id,version),review(w,(UUID)r.get("review_id")),(Integer)r.get("attempts"),(String)r.get("last_code"),instant(r.get("applied_at")));}
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
 public State state(UUID actor,UUID w){scope.requireOwner(w,actor);var s=subscription(w);var requests=db.sql("SELECT id FROM subscription_downgrade_request WHERE workspace_id=:w ORDER BY created_at DESC,id DESC LIMIT 25").param("w",w).query(UUID.class).list();return new State(w,(String)s.get("display_name"),tag(w,(Integer)s.get("version")),instant(s.get("period_end")),targets(w,s),requests.stream().map(id->request(w,id)).toList(),"Local sandbox policy: paid-to-Free at the recorded paid-period end. No refund or collection. Excess data and existing access are retained; new capacity is blocked until below allowance. Latest 25 requests shown.",now());}
 public Review preview(UUID actor,UUID w,UUID key,String expected,UUID targetId){return preview(actor,w,key,expected,targetId,false);}
 public Review cancellationPreview(UUID actor,UUID w,UUID key,String expected){return command(actor,w,"cancellation-review",key,Collections.singletonList(expected),Review.class,()->{var s=subscription(w);local(s);UUID targetId=targets(w,s).stream().filter(Target::eligible).map(Target::versionId).findFirst().orElseThrow(()->new ApiProblem(409,"CANCELLATION_POLICY_UNAVAILABLE","Cancellation requires an active local paid period and a configured Free continuation plan. Free workspace closure and live cancellation are not configured."));return preview(actor,w,key,expected,targetId,true);});}
 private Review preview(UUID actor,UUID w,UUID key,String expected,UUID targetId,boolean cancellation){return command(actor,w,cancellation?"cancellation-preview":"preview",key,Arrays.asList(expected,targetId),Review.class,()->{var s=subscription(w);local(s);match(expected,tag(w,(Integer)s.get("version")));Target t=target(w,s,targetId);Instant effective=instant(s.get("period_end"));var future=entitlements.previewAt(w,targetId,evaluationAt(effective));var nowFeatures=entitlements.evaluate(w).stream().filter(Entitlements.Decision::eligible).toList();var futureCodes=future.stream().filter(Entitlements.Decision::eligible).map(Entitlements.Decision::code).collect(java.util.stream.Collectors.toSet());var lost=nowFeatures.stream().filter(d->!futureCodes.contains(d.code())).map(Entitlements.Decision::label).toList();var retained=nowFeatures.stream().filter(d->futureCodes.contains(d.code())).map(Entitlements.Decision::label).toList();var q=new Review(UUID.randomUUID(),targetId,(Integer)s.get("version"),fingerprint(w,targetId,effective),(String)s.get("display_name"),t.name(),effective,now().plusSeconds(600),quotas(w,t.rentableLimit(),t.managerLimit()),lost,retained,"No property, unit, membership, invoice, agreement, financial record or document is deleted. Existing usage is retained. New capacity is blocked when allowance is exhausted; corrections and releases remain available.","sandbox",cancellation?new CancellationTerms("sandbox-paid-cancellation-v1","not_applicable_sandbox",null,"not_applicable_sandbox",null,"INR","Cancellation does not authorize deletion. Existing records and audit evidence are retained under their existing access rules. A production retention duration, legal holds and deletion process are not configured; no purge is scheduled.","Paid access ends at the recorded billing boundary and the workspace continues on Free. Existing members and records remain; the reviewed Free quotas apply and excess blocks new capacity. Cancellation is not workspace closure, tenancy termination or security suspension. Personal memberships remain independent."):null);db.sql("INSERT INTO subscription_downgrade_review(id,workspace_id,actor_id,snapshot,expires_at) VALUES(:id,:w,:a,CAST(:s AS jsonb),:x)").param("id",q.id()).param("w",w).param("a",actor).param("s",json.writeValueAsString(q)).param("x",java.sql.Timestamp.from(q.expiresAt())).update();audit.record(actor,w,(cancellation?"subscription.cancellation_reviewed":"subscription.downgrade_reviewed"),q.id());return q;});}
 private void validate(UUID w,Map<String,Object>s,Review r){if(r.cancellation()!=null&&!r.cancellation().policyVersion().equals("sandbox-paid-cancellation-v1"))throw new ApiProblem(409,"POLICY_CHANGED","Cancellation policy changed. Review new terms.");if((Integer)s.get("version")!=r.subscriptionVersion()||!Objects.equals(instant(s.get("period_end")),r.effectiveAt()))throw new ApiProblem(409,"SUBSCRIPTION_CHANGED","Subscription terms changed. Review a new downgrade.");target(w,s,r.targetVersionId());if(!fingerprint(w,r.targetVersionId(),r.effectiveAt()).equals(r.fingerprint()))throw new ApiProblem(409,"POLICY_CHANGED","Effective plan eligibility changed. Review the new consequences.");}
 public Request schedule(UUID actor,UUID w,UUID key,String expected,UUID reviewId){return command(actor,w,"schedule",key,Arrays.asList(expected,reviewId),Request.class,()->{var s=subscription(w);local(s);match(expected,tag(w,(Integer)s.get("version")));Review r=review(w,reviewId);if(!now().isBefore(r.expiresAt()))throw new ApiProblem(409,"APPROVAL_STALE","Review expired. Refresh usage and review again.");if(!db.sql("SELECT actor_id=:a FROM subscription_downgrade_review WHERE id=:id").param("a",actor).param("id",reviewId).query(Boolean.class).single())throw new ApiProblem(404,"REVIEW_NOT_FOUND","Downgrade review is unavailable.");validate(w,s,r);var t=target(w,s,r.targetVersionId());if(!quotas(w,t.rentableLimit(),t.managerLimit()).equals(r.quotas()))throw new ApiProblem(409,"USAGE_CHANGED","Usage changed since review. Review the current excess warnings.");if(db.sql("SELECT count(*) FROM subscription_downgrade_request WHERE workspace_id=:w AND (status IN('scheduled','review_required') OR review_id=:r)").param("w",w).param("r",reviewId).query(Long.class).single()>0||db.sql("SELECT count(*) FROM subscription_upgrade_change WHERE workspace_id=:w AND status IN('awaiting_payment','payment_unknown','review_required')").param("w",w).query(Long.class).single()>0)throw new ApiProblem(409,"SUBSCRIPTION_CHANGE_PENDING","Resolve the existing subscription change first.");UUID id=UUID.randomUUID();db.sql("INSERT INTO subscription_downgrade_request(id,workspace_id,actor_id,review_id,status,effective_at) VALUES(:id,:w,:a,:r,'scheduled',:at)").param("id",id).param("w",w).param("a",actor).param("r",reviewId).param("at",java.sql.Timestamp.from(r.effectiveAt())).update();audit.record(actor,w,action(r,"scheduled"),id);notices.record(actor,w,id,"scheduled",1,r.cancellation()!=null);return request(w,id);});}
 public Request transition(UUID actor,UUID w,UUID id,UUID key,String expected,String action){return command(actor,w,action+":"+id,key,Arrays.asList(expected,action),Request.class,()->{var r=request(w,id);match(expected,r.etag());if(action.equals("cancel")){if(!Set.of("scheduled","review_required").contains(r.status()))throw new ApiProblem(409,"STATE_CONFLICT","Only pending downgrades can be cancelled.");db.sql("UPDATE subscription_downgrade_request SET status='cancelled',version=version+1,lease_token=NULL,lease_until=NULL WHERE id=:id").param("id",id).update();}else{if(!r.status().equals("review_required"))throw new ApiProblem(409,"STATE_CONFLICT","Only a request requiring review can be retried.");if(!db.sql("SELECT lmt_is_workspace_owner(workspace_id,actor_id) FROM subscription_downgrade_request WHERE id=:id").param("id",id).query(Boolean.class).single())throw new ApiProblem(409,"AUTHORITY_REVIEW_REQUIRED","The original requester lost authority. Cancel and create a new reviewed request under current authority.");var s=subscription(w);local(s);validate(w,s,r.review());db.sql("UPDATE subscription_downgrade_request SET status='scheduled',version=version+1,attempts=0,last_code=NULL,next_attempt_at=clock_timestamp(),lease_token=NULL,lease_until=NULL WHERE id=:id").param("id",id).update();}audit.record(actor,w,action(r.review(),action),id);notices.record(actor,w,id,action,r.version()+1,r.review().cancellation()!=null);return request(w,id);});}
 private String action(Review r,String outcome){return "subscription."+(r.cancellation()!=null?"cancellation_":"downgrade_")+outcome;}
 @Transactional(readOnly=true,isolation=org.springframework.transaction.annotation.Isolation.REPEATABLE_READ)
 public State cancellationState(UUID actor,UUID w){var s=state(actor,w);return new State(s.workspaceId(),s.currentPlan(),s.etag(),s.periodEnd(),s.targets(),s.requests().stream().filter(r->r.review().cancellation()!=null).toList(),"Local sandbox cancellation ends paid access at the recorded period end and continues on Free. No real refund or credit is due from simulated payments. Records are retained; this does not close the workspace or end any tenancy. Free workspace closure and live cancellation are not configured. Latest cancellation requests within the last 25 shared subscription transitions are shown.",s.asOf());}
 public Request scheduleCancellation(UUID actor,UUID w,UUID key,String expected,UUID reviewId){scope.requireOwner(w,actor);if(review(w,reviewId).cancellation()==null)throw new ApiProblem(409,"CANCELLATION_REVIEW_REQUIRED","Review cancellation terms before confirming.");return schedule(actor,w,key,expected,reviewId);}
 public Request transitionCancellation(UUID actor,UUID w,UUID id,UUID key,String expected,String action){scope.requireOwner(w,actor);if(request(w,id).review().cancellation()==null)throw new ApiProblem(404,"CANCELLATION_NOT_FOUND","Cancellation request is unavailable.");return transition(actor,w,id,key,expected,action);}
 public List<Claim> claim(){return db.sql("SELECT * FROM lmt_claim_due_downgrades()").query((r,n)->new Claim(r.getObject("id",UUID.class),r.getObject("workspace_id",UUID.class),r.getObject("actor_id",UUID.class),r.getObject("token",UUID.class))).list();}
 public void fail(Claim c,String code){db.sql("SELECT lmt_fail_downgrade(:id,:token,:code)").param("id",c.id()).param("token",c.token()).param("code",code).query().singleRow();}
 public void apply(Claim c){
  scope.scope(c.actorId());db.sql("SELECT pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","membership:"+c.workspaceId()).query().singleRow();
  if(!db.sql("SELECT lmt_is_workspace_owner(:w,:a)").param("w",c.workspaceId()).param("a",c.actorId()).query(Boolean.class).single()){fail(c,"AUTHORITY_REVOKED");return;}
  lock(c.actorId(),c.workspaceId());var row=db.sql("SELECT * FROM subscription_downgrade_request WHERE id=:id FOR UPDATE").param("id",c.id()).query().singleRow();if(!row.get("status").equals("scheduled")||!c.token().equals(row.get("lease_token"))||instant(row.get("lease_until")).isBefore(now()))return;
  if(instant(row.get("effective_at")).isAfter(now()))return;var r=review(c.workspaceId(),(UUID)row.get("review_id"));var s=subscription(c.workspaceId());if(!config.sandbox||!s.get("mode").equals("sandbox")){fail(c,"MODE_UNAVAILABLE");return;}if(s.get("workspace_status").equals("suspended")){fail(c,"SECURITY_SUSPENDED");return;}
  try{validate(c.workspaceId(),s,r);}catch(ApiProblem e){fail(c,Set.of("SUBSCRIPTION_CHANGED","TARGET_UNAVAILABLE","POLICY_CHANGED").contains(e.code)?e.code:"JOB_FAILED");return;}
  var t=target(c.workspaceId(),s,r.targetVersionId());db.sql("SELECT resource FROM workspace_grant WHERE workspace_id=:w ORDER BY resource FOR UPDATE").param("w",c.workspaceId()).query(String.class).list();
  db.sql("UPDATE workspace_subscription SET plan_version_id=:p,status='active_free',version=version+1,period_start=NULL,period_end=NULL,base_amount=NULL,interval_months=NULL WHERE workspace_id=:w").param("p",r.targetVersionId()).param("w",c.workspaceId()).update();
  for(String resource:List.of("managers","rentable_items"))db.sql("UPDATE workspace_grant SET allowance=:limit WHERE workspace_id=:w AND resource=:r").param("limit",resource.equals("managers")?t.managerLimit():t.rentableLimit()).param("w",c.workspaceId()).param("r",resource).update();
  db.sql("UPDATE subscription_downgrade_request SET status='applied',version=version+1,applied_at=clock_timestamp(),lease_token=NULL,lease_until=NULL,last_code=NULL WHERE id=:id").param("id",c.id()).update();audit.record(c.actorId(),c.workspaceId(),action(r,"applied"),c.id());notices.record(c.actorId(),c.workspaceId(),c.id(),"applied",(Integer)row.get("version")+1,r.cancellation()!=null);
 }
}
